registerRefData('nsw-cond-n-4021',{"id":4021,"pan":null,"ref":"DA-2017/1729","address":"Lot 1 Dp 720015 And Lots 20-24 Sec 4 Dp 1258, 25 - 27 Denison Street, Wollongong","description":"Proposed office building above basement car parking","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2018-07-27","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPS-2018STH001!20190615T003547.356 GMT","sha256":"6a6def2d750c540694251a4e18d26b204dbc6f25d1f0c992e8788aa68e27f48b","pages":33,"layout":"numbered","n":126,"fetched_at":"2026-08-17T01:20:28+00:00","file":"n/4021.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/proposed-office-building-above-basement-car-parking","lga":"WOLLONGONG","conditions":[{"label":"1","code":null,"number":"1","title":"","text":"PANEL REF - LGA - DA NO. 2018STH001 - Wollongong - DA -2017/1729","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"","text":"PROPOSED DEVELOPMENT Commercial - demolition of existing structures and construction of a seven\n(7) storey commercial building over three (3) levels of basement parking","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS 25 - 27 Denison Street, WOLLONGONG","text":"","stage":"general","stage_basis":"heading","page":3},{"label":"4","code":null,"number":"4","title":"","text":"APPLICANT/OWNER Applicant - ADM Architects; Owner - Defono Pty Ltd and Pagibu Pty Ltd","stage":"general","stage_basis":"heading","page":3},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT CIV > $20 million, lodged before 1 March 2018","stage":"general","stage_basis":"heading","page":3},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n• Environmental planning instruments:\no State Environmental Planning Policy NO 55 - Remediation of Land\no State Environmental Planning Policy (Infrastructure) 2007\no State Environmental Planning Policy (State and Regional\nDevelopment) 2011\no Wollongong Local Environmental Plan 2009\n• Draft environmental planning instruments: Nil\n• Development control plans:\no Wollongong Development Control Plan 2009\no Wollongong Section 94A Development Contributions Plan 2017\n• Planning agreements: Nil\n• Provisions of the Environmental Planning and Assessment Regulation\n2000: Nil\n• Coastal zone management plan: Nil\n• The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and economic\nimpacts in the locality\n• The suitability of the site for the development\n• Any submissions made in accordance with the Environmental Planning\nand Assessment Act 1979 or regulations\n• The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":3},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n• Council assessment report: 18 July 2017\n• Written submissions during public exhibition: Nil\n• Verbal submissions at the public meeting:\no On behalf of the applicant - Angelo Di Martino","stage":"general","stage_basis":"heading","page":3},{"label":"8","code":null,"number":"8","title":"MEETINGS AND SITE","text":"INSPECTIONS BY THE PANEL\n• Site inspection 1 May 2018\n• Final briefing meeting to discuss council’s recommendation, 27 July\n2018. Attendees:\no Panel members: Pam Allan (Chair), Alison McCabe, Renata\nBrooks, Michael Mantei, David Brown\no Council assessment staff: Anne Starr, Mark Fowler, Pier Panozzo,\nRebecca Welsh, John Wood, Paul Marskell, Andrew Heaven,\nTheresa Whittaker, Mark Riordan, Andrew Carfield, Nigel Lamb","stage":"general","stage_basis":"heading","page":3},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval subject to deferred commencement consent","stage":"general","stage_basis":"heading","page":3},{"label":"10","code":null,"number":"10","title":"","text":"DRAFT CONDITIONS Attached to the council assessment report and addendum circulated at the\nmeeting.\nAppendix One - Draft Conditions - as tabled at the meeting on 27/07/18\nDeferred Commencement Conditions\nThe development application has been determined by granting deferred commencement consent subject\nto the following conditions:\n(i) The Development Consent shall not operate until the applicant satisfies Council, within 12\nmonths of the date of this consent, that it has obtained approval/certification from Sydney Trains\nas to the following matters and the approval/certification has been forwarded to the Council:-\nThe Applicant shall prepare and provide to Sydney Trains for approval/certification the following\nfinal version items in compliance with relevant ASA Standards\n(https://www.transport.nsw.gov.au/industry/standards-and-accreditation/standards):\n1. Geotechnical and Structural report/drawings that meet Sydney Trains requirements. The\nGeotechnical Report must be based on actual borehole testing conducted on the site\nclosest to the rail corridor, and include a specific section relating to the Standards and any\npotential impacts (including demolition- and excavation- induced vibrations) to the rail\ncorridor including tracks and assets.\n2. Construction methodology with construction details pertaining to structural support during\nexcavation. The Applicant is to be aware that Sydney Trains will not permit any rock\nanchors/bolts (whether temporary or permanent) within its land or easements.\n3. Cross sectional drawings showing the rail corridor, sub soil profile, proposed basement\nexcavation, structural design of sub ground support adjacent to the rail corridor, distance\nfrom the centre of the nearest track to the nearest point of excavation, distance from the\noverhead high voltage aerial lines to the boundary, and set back of the building to the\nboundary. Horizontal measurements and RL depths are to be verified by a Registered\nSurveyor.\n4. Detailed accurate Survey Plan showing the relationship of the proposed developed with\nrespect to Sydney Trains easement and rail corridor land including distance verified by a\nregistered surveyor from the boundary to the centre of the nearest track and overhead\nhigh voltage aerial lines.\n5. If required by Sydney Trains, an FE analysis which assesses the different stages of loading-\nunloading of the site and its effect on the rock mass surrounding the rail corridor.\n(ii) The developer must satisfy Council, within 12 months of the date shown on the top of this consent,\nthat the matters specified in condition number (i) have been complied with. Failure to satisfy\nCouncil within that time period will lapse this development consent\n(iii) If compliance with the matters contained in condition number (i) results in a substantial variation\nto the development approved deferred commencement, a new development application must be\nsubmitted.\nOnce Council is satisfied that the matters contained in condition number (i) have been complied with and\nthe developer has been notified in writing of such compliance, the following conditions shall apply in\nrespect of the approved development:\nApproved Plans and Specifications","stage":"general","stage_basis":"heading","page":3},{"label":"1","code":null,"number":"1","title":"The development shall be implemented substantially in accordance with the details and","text":"specifications to be inserted by Council prepared by ADM Architects and any details on the\napplication form, and with any supporting information received, except as amended by the\nconditions specified and imposed hereunder.\nGeneral Matters","stage":"general","stage_basis":"heading","page":4},{"label":"2","code":null,"number":"2","title":"Building Work - Compliance with the Building Code of Australia","text":"All building work must be carried out in compliance with the provisions of the Building Code of\nAustralia.","stage":"general","stage_basis":"heading","page":5},{"label":"3","code":null,"number":"3","title":"Construction Certificate","text":"A Construction Certificate must be obtained from Council or an Accredited Certifier prior to work\ncommencing.\nA Construction Certificate certifies that the provisions of Clauses 139-148 of the Environmental\nPlanning and Assessment Amendment Regulations, 2000 have been satisfied, including compliance\nwith all relevant conditions of Development Consent and the Building Code of Australia.\nNote: The submission to Council of two (2) copies of all stamped Construction Certificate plans and\nsupporting documentation is required within two (2) days from the date of issue of the\nConstruction Certificate, in the event that the Construction Certificate is not issued by Council.","stage":"general","stage_basis":"heading","page":5},{"label":"4","code":null,"number":"4","title":"Disability Discrimination Act 1992","text":"This consent does not imply or confer compliance with the requirements of the Disability\nDiscrimination Act 1992.\nIt is the responsibility of the applicant to guarantee compliance with the requirements of the\nDisability Discrimination Act 1992. The current Australian Standard AS1428.1 (2009) - Design for\nAccess and Mobility is recommended to be referred for specific design and construction\nrequirements, in order to provide appropriate access to all persons within the building.","stage":"general","stage_basis":"heading","page":5},{"label":"5","code":null,"number":"5","title":"Maintenance of Access to Adjoining Properties","text":"Access to all properties not the subject of this approval must be maintained at all times and any\nalteration to access to such properties, temporary or permanent, must not be commenced until\nsuch time as written evidence is submitted to Council or the Principal Certifying Authority indicating\nagreement by the affected property owners.","stage":"general","stage_basis":"heading","page":5},{"label":"6","code":null,"number":"6","title":"Protection of Public Infrastructure","text":"Council must be notified in the event of any existing damage to any of its infrastructure such as the\nroad, kerb and gutter, road shoulder, footpath, drainage structures and street trees fronting the\ndevelopment site, prior to commencement of any work.\nAdequate protection must be provided for Council infrastructure prior to work commencing and\nduring building operations.\nAny damage to Council’s assets shall be made good, prior to the issue of any Occupation Certificate\nor commencement of the operation.","stage":"general","stage_basis":"heading","page":5},{"label":"7","code":null,"number":"7","title":"Geotechnical","text":"• A dilapidation report is required for all structures located within the zone of influence of the\nproposed earthworks as determined by the geotechnical consultant.\n• No disturbance of ground is to occur beyond site boundaries. A minimum buffer between site\nboundaries and the construction of retaining structures is to be recommended by the\ngeotechnical consultant to ensure adjoin ing property is not adversely impacted upon by this\ndevelopment.\n• Hard bedrock where encountered will be difficult to excavate. Alternative excavation methods\nshould be considered to minimise noise and vibration.\n• All excavations need to be supported during and after construction particularly to protect\nadjoining property with nearby existing development.\n• Retaining wall design is not to include anchors extending on to adjoining property without the\nwritten consent of the adjoining property owner.\n• All work is to be in accordance with the geotechnical recommendations contained in the report\ndated 8 December 2017 by Network Geotechnics and any subsequent geotechnical report\nrequired to address unanticipated conditions encountered during construction.\n• An earthworks plan is to be developed by the geotechnical consultant prior to start of\nearthworks.\n• All recommendations of the geotechnical consultant in their geotechnical report dated 8\nDecember 2017 are to be accommodated in the earthworks plan.\n• The earthworks plan may require modification in light of any subsequent geotechnical reports\ncommissioned to address unforeseen geotechnical conditions encountered during the site\npreparation earthworks.\n• All earthworks including drainage, retaining wall and footing construction is to be subject to Level\n1 geotechnical supervision as defined in Australian Standard AS3798 Guidelines for Earthworks\nfor Commercial and Residential Developments. Where necessary amendments are to be made\nto the designs during construction based on supplementary geotechnical advice given during the\nsupervision to ensure that the completed works accommodates all encountered geotechnical\nconstraints.\n• All excavations for foundations are to be inspected by the geotechnical consultant and cer tified\nthat the ground has been suitably prepared for the placement of footings.","stage":"general","stage_basis":"heading","page":5},{"label":"8","code":null,"number":"8","title":"Water Sensitive Urban Design (WSUD)","text":"The water cycling management treatment nodes shall be constructed as per the Water Cycle\nManagement Study prepared by Jones Nicholson Consulting Engineering dated December 2017 to\nachieve the treatment goals for the removal of pollutants and nutrients which shall be: Gross\nPollutants (GP) - 90%, Total Suspended Solids (TSS) - 85%, Total Phosphorus (TP) - 60% and Total\nNitrogen (TN) - 45%.","stage":"general","stage_basis":"heading","page":6},{"label":"9","code":null,"number":"9","title":"Advertising Signage","text":"Any advertising signs require separate Council approval unless such signage is exempt.","stage":"general","stage_basis":"heading","page":6},{"label":"10","code":null,"number":"10","title":"Lot Consolidation","text":"The subject allotments shall be consolidated prior to the issue of an Occupation Certificate for the\nbuilding.","stage":"general","stage_basis":"heading","page":6},{"label":"11","code":null,"number":"11","title":"Occupation Certificate","text":"An Occupation Certificate must be issued by the Principal Certifying Authority prior to occupation\nor use of the development. In issuing an Occupation Certificate, the Principal Certifying Authority\nmust be satisfied that the requirements of Section 109H of the Environmental Planning and\nAssessment Act 1979, have been complied with as well as all of the conditions of the Development\nConsent.\nSydney Trains Conditions","stage":"general","stage_basis":"heading","page":6},{"label":"12","code":null,"number":"12","title":"","text":"Prior to the issue of a Construction Certificate, the Applicant shall undertake a services search to\nestablish the existence and location of any rail services. Persons performing the service search shall\nuse equipment that will not have any impact on rail services and signalling. Should rail services be\nidentified within the subject development site, the Applicant must discuss with Sydney Trains as to\nwhether these services are to be relocated or incorporated within the development site.","stage":"before_cc","stage_basis":"text-under-general-heading","page":6},{"label":"13","code":null,"number":"13","title":"","text":"Prior to the commencement of works, prior to the issue of the Occupation Certificate, or at any\ntime during the excavation and construction period deemed necessary by Sydney Trains, a joint\ninspection of the rail infrastructure and property in the vicinity of the project is to be carried out by\nrepresentatives from Sydney Trains and the Applicant. These dilapidation surveys will establish the\nextent of any existing damage and enable any deterioration during construction to be observed.\nThe submission of a detailed dilapidation report will be required unless otherwise notified by\nSydney Trains.","stage":"before_work","stage_basis":"text-under-general-heading","page":6},{"label":"14","code":null,"number":"14","title":"","text":"Given the possible likelihood of objects being dropped, thrown or blown onto the rail corridor from\nbalconies, windows and other external features (e.g. roof terraces and external fire escapes) that\nface the rail corridor, the Applicant is required to install measures (e.g. awning windows, louvres,\nenclosed balconies etc.) which prevent the throwing of objects onto the rail corridor. The Principal\nCertifying Authority shall not issue the Construction Certificate until it has confirmed that these\nmeasures are to be installed and have been indicated on the Construction Drawings.","stage":"general","stage_basis":"heading","page":7},{"label":"15","code":null,"number":"15","title":"","text":"A final Electrolysis Report based on the final approved development is to be prepared prior to the\nissue of a construction certificate. The Applicant must incorporate in the development all the\nmeasures recommended in the report to control that risk.","stage":"general","stage_basis":"heading","page":7},{"label":"16","code":null,"number":"16","title":"","text":"A risk analysis, which shall determine the required level of derailment protection (if any), shall be\ncarried out in consultation with Sydney Trains. This risk analysis will determine the redundancy\nrequirements or the minimum collision loads specified in Australian Standard AS5100 that needs to\nbe complied with. The risk assessment is to be prepared in accordance with the Sydney Trains\nSafety Management System.\nThe Principal Certifying Authority shall not issue the Construction Certificate until it has received\nwritten confirmation from RailCorp that the risk analysis has been prepared and the Principal\nCertifying Authority has also confirmed that the measures recommended in this risk analysis have\nbeen indicated on the Construction Drawings.","stage":"general","stage_basis":"heading","page":7},{"label":"17","code":null,"number":"17","title":"","text":"The design, installation and use of lights, signs and reflective materials, whether permanent or\ntemporary, which are (or from which reflected light might be) visible from the rail corridor must\nlimit glare and reflectivity to the satisfaction of Sydney Trains. The Principal Certifying Authority\nshall not issue the Construction Certificate until written confirmation has been received from\nSydney Trains confirming that this condition has been satisfied.","stage":"general","stage_basis":"heading","page":7},{"label":"18","code":null,"number":"18","title":"","text":"The proposed development is to comply with the deemed-to-satisfy provisions in the Department\nof Planning’s document titled “Development Near Rail Corridors and Busy Roads- Interim\nGuidelines”.","stage":"general","stage_basis":"heading","page":7},{"label":"19","code":null,"number":"19","title":"","text":"Prior to the issue of a Construction Certificate a Risk Assessment/Management Plan regarding any\npotential risk to or from the rail corridor and assets, and detailed Safe Work Method Statements\n(SWMS) for the proposed works are to be submitted to Sydney Trains for review and comment on\nthe impacts on the rail corridor. The Principal Certifying Authority shall not issue the Construction\nCertificate until written confirmation has been received from Sydney Trains confirming that this\ncondition has been satisfied.","stage":"before_cc","stage_basis":"text-under-general-heading","page":7},{"label":"20","code":null,"number":"20","title":"","text":"No metal ladders, tapes and plant/machinery, or conductive material are to be used within 6\nhorizontal metres of any live electrical equipment. This applies to the train pantographs and 1500V\ncatenary, contact and pull-off wires of the adjacent tracks, and to any high voltage aerial supplies\nwithin or adjacent to the rail corridor.","stage":"general","stage_basis":"heading","page":7},{"label":"21","code":null,"number":"21","title":"","text":"Given the proximity of the existing building to the rail corridor boundary prior to the undertaking of\nany demolition works, demolition methodology and works programme is to be submitted to\nSydney Trains for review and endorsement prior to the undertaking of those works. Demolition\nshall not be undertaken until written confirmation has been provided by Sydney Trains that this\ncondition has been complied with.","stage":"general","stage_basis":"heading","page":7},{"label":"22","code":null,"number":"22","title":"","text":"Prior to the issuing of a Construction Certificate the Applicant is to submit to Sydney Trains a plan\nshowing all craneage and other aerial operations for the development and must comply with all\nSydney Trains requirements. The Principal Certifying Authority shall not issue the Construction\nCertificate until written confirmation has been received from Sydney Trains confirming that this\ncondition has been satisfied.","stage":"general","stage_basis":"heading","page":7},{"label":"23","code":null,"number":"23","title":"","text":"If required, on completion of works the applicant shall provide a Validation Contamination\nResponse report to Sydney Trains for review.","stage":"general","stage_basis":"heading","page":8},{"label":"24","code":null,"number":"24","title":"","text":"Excess soil is not allowed to enter, be spread or stockpiled within the rail corridor (and its\neasement) and must be adequately managed/ disposed of.","stage":"general","stage_basis":"heading","page":8},{"label":"25","code":null,"number":"25","title":"","text":"Given the development site’s location next to the rail corridor, drainage from the development\nmust be adequately managed/ disposed of and not allowed to be discharged into the corridor (and\nits easements) unless prior approval has been obtained from Sydney Trains.","stage":"general","stage_basis":"heading","page":8},{"label":"26","code":null,"number":"26","title":"","text":"No work is permitted within the rail corridor, or its easements, at any time unless prior approval jor\nan Agreement has been entered into with Sydney Trains. Where the Applicant proposes to enter\nthe rail corridor, the Principal Certifying Authority shall not issue a Construction Certificate until\nwritten confirmation has been received from Sydney Trains confirming that its approval has been\ngranted.","stage":"general","stage_basis":"heading","page":8},{"label":"27","code":null,"number":"27","title":"","text":"Prior to the commencement of works the Applicant shall peg-out the common property boundary\nwith RailCorp’s land. This work is to be undertaken by a registered surveyor.","stage":"before_work","stage_basis":"text-under-general-heading","page":8},{"label":"28","code":null,"number":"28","title":"","text":"Prior to the commencement of works appropriate fencing is to be in place along the rail corridor to\nprevent unauthorised access to the rail corridor during construction. Details of the type of fencing\nand the method of erection are to be to the satisfaction of Sydney Trains prior to the fencing work\nbeing undertaken.","stage":"before_work","stage_basis":"text-under-general-heading","page":8},{"label":"29","code":null,"number":"29","title":"","text":"The development shall have appropriate fencing fit for the future usage of the development site to\nprevent unauthorised access to the rail corridor by future occupants of the development. Prior to\nthe issuing of an Occupation Certificate the Applicant shall liaise with Sydney Trains regarding the\nadequacy of any existing fencing along the rail corridor boundary. Details of the type of new\nfencing to be installed and the method of erection are to be to the satisfaction of Sydney Trains\nprior to the fencing work being undertaken.","stage":"general","stage_basis":"heading","page":8},{"label":"30","code":null,"number":"30","title":"","text":"Prior to the issuing of a Construction Certificate the applicant is to submit to Sydney Trains for\nreview and endorsement a report detailing all Machinery to be used during\nexcavation/construction. The Principal Certifying Authority is not to issue the Construction\nCertificate until it has received written confirmation from Sydney Trains that this condition has\nbeen complied with.","stage":"general","stage_basis":"heading","page":8},{"label":"31","code":null,"number":"31","title":"","text":"To ensure that graffiti can be easily removed, the Applicant is to ensure that fencing along the rail\ncorridor is coated with anti-graffiti paint or other coating.","stage":"general","stage_basis":"heading","page":8},{"label":"32","code":null,"number":"32","title":"","text":"During all stages of the development, environmental legislation and regulations will be complied\nwith.","stage":"general","stage_basis":"heading","page":8},{"label":"33","code":null,"number":"33","title":"","text":"During all stages of the development, extreme care shall be taken to prevent any form of pollution\n(including dust) entering the railway corridor. Any form of pollution that arises as a consequence of\nthe development activities shall remain the full responsibility of the Applicant.","stage":"general","stage_basis":"heading","page":8},{"label":"34","code":null,"number":"34","title":"","text":"During all stages of the development extreme care shall be taken to prevent environmental harm\nwithin the railway corridor. Any form of environmental harm to areas within the railway corridor or\nlegislative non-compliance that arises as a consequence of the development activities shall remain\nthe full responsibility of the Applicant.","stage":"general","stage_basis":"heading","page":8},{"label":"35","code":null,"number":"35","title":"","text":"There is a need to ensure that the roots and foliage of trees being planted beside the rail corridor\ndo not have an impact on the rail corridor and nearby high voltage assets. The development\nlandscaping and planting plan should be submitted to Sydney Trains for review and endorsement.","stage":"general","stage_basis":"heading","page":8},{"label":"36","code":null,"number":"36","title":"","text":"The applicant shall not at any stage (during works and post development) block the rail corridor\naccess gate on Hercules Street and shall make provision for easy and ongoing 24/7 access by rail\nvehicles, plant and equipment to support maintenance and emergency activities. Prior to\ncommencement of works, the applicant shall consult with Sydney Trains regarding any potential\nimpact by the development to the existing rail corridor access gate to ensure easy and ongoing\n24/7 access to the rail corridor is maintained.","stage":"general","stage_basis":"heading","page":9},{"label":"37","code":null,"number":"37","title":"","text":"No scaffolding or hoarding is to be used facing the rail corridor unless prior written approval has\nbeen obtained from Sydney Trains. To obtain approval the proponent will be required to submit\ndetails of the scaffolding and hoarding, the means of erecting and securing this scaffolding, the\nmaterial to be used, and the type of screening to be installed to prevent objects falling onto the rail\ncorridor. Unless agreed to by Sydney Trains in writing, scaffolding shall not be erected without\nisolation and protection panels.","stage":"general","stage_basis":"heading","page":9},{"label":"38","code":null,"number":"38","title":"","text":"Sydney Trains advises they have a 33kV H/V aerial transmission line near to this site and any works,\nscaffolding and crane movements within 6 metres of the nearest transmission line conductor must\nbe discussed and approved by Sydney Trains beforehand. All works within 6 metres of the nearest\ntransmission line conductor must comply with:\n▪ ISSC 20 - Guideline for the Management of Activities within Electricity Easements and Close\nto Electricity Infrastructure.\n▪ The Safe Approach Distances (SADs) in the Sydney Trains Document titled “SMS-06-GD-0268\n- Working Around Electrical Equipment”.","stage":"general","stage_basis":"heading","page":9},{"label":"39","code":null,"number":"39","title":"","text":"Unless advised by Sydney Trains in writing, all excavation, shoring and piling works within 25m of\nthe rail corridor are to be supervised by a geotechnical engineer experienced with such excavation\nprojects.","stage":"general","stage_basis":"heading","page":9},{"label":"40","code":null,"number":"40","title":"","text":"No rock anchors/bolts are to be installed into Sydney Trains property or easements.","stage":"general","stage_basis":"heading","page":9},{"label":"41","code":null,"number":"41","title":"","text":"Sydney Trains and Transport for NSW, and persons authorised by them for this purpose, are\nentitled to inspect the site of the approved development and all structures to enable it to consider\nwhether those structures on that site have been or are being constructed and maintained in\naccordance with these conditions of consent, on giving reasonable notice to the principal\ncontractor for the approved development or the owner or occupier of the part of the site to which\naccess is sought.","stage":"general","stage_basis":"heading","page":9},{"label":"42","code":null,"number":"42","title":"","text":"The developer must provide a plan of how future maintenance of the development facing the rail\ncorridor is to be undertaken. The maintenance plan is to be submitted to Sydney Trains prior to the\nissuing of the Occupancy Certificate. The Principal Certifying Authority shall not issue an Occupation\nCertificate until written confirmation has been received from Sydney Trains advising that the\nmaintenance plan has been prepared to its satisfaction.","stage":"general","stage_basis":"heading","page":9},{"label":"43","code":null,"number":"43","title":"","text":"Prior to the issuing of an Occupation Certificate the Applicant is to submit the as-built drawings to\nSydney Trains and Council. The as-built drawings shall indicate that there has been no\nencroachment into Sydney Trains land or easements. The Principal Certifying Authority is not to\nissue the Occupation Certificate until written confirmation has been received from Sydney Trains\nconfirming that this condition has been satisfied.","stage":"general","stage_basis":"heading","page":9},{"label":"44","code":null,"number":"44","title":"","text":"Where a condition of consent requires Sydney Trains or Transport for NSW endorsement the\nPrincipal Certifying Authority is not to issue a Construction Certificate or Occupancy Certificate, as\nthe case may be, until written confirmation has been received from those entities that the\nparticular condition has been complied with. The issuing of staged Construction Certificates dealing\nwith specific works and compliance conditions can be issued subject to written agreement from\nthose entities to which the relevant conditions applies.","stage":"general","stage_basis":"heading","page":9},{"label":"45","code":null,"number":"45","title":"","text":"Copies of any certificates, drawings, approvals/certification or documents endorsed by, given to or\nissued by Sydney Trains must be submitted to Council for its records prior to the issuing of a\nConstruction Certificate.","stage":"general","stage_basis":"heading","page":10},{"label":"46","code":null,"number":"46","title":"","text":"Any conditions issued as part of Sydney Trains approval/certification of any documentation for\ncompliance with the Sydney Trains conditions of consent, those approval/certification conditions\nwill also form part of the consent conditions that the Applicant is required to comply with.","stage":"general","stage_basis":"heading","page":10},{"label":"47","code":null,"number":"47","title":"","text":"If required, prior to the issue of a Construction Certificate the Applicant is to contact Sydney Trains\nEngineering Management Interfaces to determine the need for public liability insurance cover. If\ninsurance cover is deemed necessary this insurance be for sum as determined by Sydney Trains and\nshall not contain any exclusion in relation to works on or near the rail corridor, rail infrastructure.\nThe Applicant is to contact Sydney Trains Engineering Management Interfaces to obtain the level of\ninsurance required for this particular proposal. Prior to issuing the Construction Certificate the\nPrincipal Certifying Authority must witness written proof of this insurance in conjunction with\nSydney Trains written advice to the Applicant on the level of insurance required.","stage":"general","stage_basis":"heading","page":10},{"label":"48","code":null,"number":"48","title":"","text":"If required, prior to the issue of a Construction Certificate the Applicant is to contact Sydney Trains\nEngineering Management Interfaces to determine the need for the lodgement of a Bond or Bank\nGuarantee for the duration of the works. The Bond/Bank Guarantee shall be for the sum\ndetermined by Sydney Trains. Prior to issuing the Construction Certificate the Principal Certifying\nAuthority must witness written advice from Sydney Trains confirming the lodgement of this\nBond/Bank Guarantee.","stage":"general","stage_basis":"heading","page":10},{"label":"49","code":null,"number":"49","title":"","text":"If required by Sydney Trains, a track monitoring plan (including instrumentation and the monitoring\nregime during excavation and construction phases) is to be submitted to Sydney Trains for review\nand endorsement prior to the issuing of a Construction Certificate. The Principal Certifying\nAuthority is not to issue a Construction Certificate until written confirmation has been received\nfrom Sydney Trains advising of the need to undertake the track monitoring plan, and if required,\nthat it has been endorsed.","stage":"general","stage_basis":"heading","page":10},{"label":"50","code":null,"number":"50","title":"Demolition Plan","text":"Prior to the release of a Construction Certificate or the commencement of any works at the site, a\ndetailed demolition work plan prepared by a suitably qualified person shall be submitted to and\napproved by Council. The plan shall be prepared in accordance with Australian Standard AS 2601-\n2001 - The Demolition of Structures, and shall include the following details:\n• Identification of any hazardous materials,\n• the proposed method and timing of demolition works;\n• the expected duration of the demolition works;\n• an outline of the machinery and equipment to be employed to undertake the demolition works;\n• precautions to be employed to minimise any dust nuisance and;\n• the disposal methods for hazardous materials.\nA Construction Certificate shall not be released by the Principal Certifying Authority and no\ndemolition works shall commence until such time as Council’s written approval has been obtained\nfor the demolition plan. The approved demolition plan shall be complied with at times.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"51","code":null,"number":"51","title":"Construction Management Plan","text":"Prior to the release of a Construction Certificate or the commencement of any works at the site, a\ndetailed Construction Management Plan (CMP) prepared by a suitably qualified person shall be\nsubmitted to and approved by Council. The construction management plan shall include (but not be\nlimited to) the following details:\na details of staging and timing\nb plan of proposed construction storage area;\nc parking for construction workers during the demolition and construction phases;\nd the type of materials/plant/ equipment to be transported to and stored at the site and how is it\nto be transported and stored;\ne timing of delivery of materials;\nf the proposed access points to the site during construction;\ng treatment of barricading/ hoarding for construction/and restricting access;\nh address all environmental aspects of the development's demolition and construction phases including\nsoil and water management/erosion and sediment control plan; noise and vibration management plan;\ndust suppression/ dust management plan; waste management plan and litter control;\ni construction noise mitigation measures; and\nj timing of waste collection during construction.\nA Construction Certificate shall not be released by the Principal Certifying Authority and no works\nshall commence until such time as Council’s written approval has been obtained for the\nconstruction management plan. The approved construction management plan shall be complied\nwith at times.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"52","code":null,"number":"52","title":"Site Environmental Management Plan","text":"Prior to the issue of a Construction Certificate, the developer is required to submit to the PCA a site\nconstruction environmental management which shall address, as a minimum, the vehicle traffic,\nodour and vapour, dust, plant and machinery noise, water and sediment management, surface\nwater, subsurface seepage and accumulated excavation water, sediment from equipment and\ncleaning operations, site security, working hours, contact information, incident response and\ncontingency management. The approved Site Environmental Management Plan shall be complied\nwith at times during the course of demolition and construction.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"53","code":null,"number":"53","title":"","text":"Site Assessment Report (Stage II) and Remediation Action Plan Under CLM Act 1997.\nThe Stage II (detail site assessment report) to assess the nature and volumes of soil contamination\nand identify areas of environmental concern (AEC). Based on the Stage-II assessment report a stage\nIII (remediation action plan - RAP) must be prepared so that site is suitable for proposed\ndevelopment. The Stage II and III reports must be prepared as per the Guidelines for Consultants\nReporting on Contaminated Sites, published by NSW Office of Environment & Heritage. August\n2011.\nThe report shall be prepared by qualified and experienced consultant who has one of the following\ncertification schemes: (1) the Site Contamination Practitioners Australia (SCPA) scheme; (2) the\nEnvironment Institute of Australia and New Zealand’s (EIANZ) Contaminated Land Assessment\nSpecialist Certified Environmental Practitioner (CLA Specialist CEnvP) scheme; or (3) the Soil Science\nAustralia (SSA) Certified Professional Soil Scientist Contaminated Site Assessment and Management\n(CPSS CSAM) certification.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"54","code":null,"number":"54","title":"Section 73 Compliance Certificate","text":"A Section 73 Compliance Certificate under the Sydney Water Act 1994 must be obtained from\nSydney Water Corporation. Application must be made through an authorised Water Servicing\nCoordinator. Please refer to the “Builders and Developers” section of the web site\nwww.sydneywater.com.au then search to “Find a Water Servicing Coordinator”. Alternatively,\ntelephone 13 20 92 for assistance.\nFollowing application, a “Notice of Requirements” will advise of water and sewer infrastructure\nto be built and charges to be paid. Please make early contact with the Coordinator, since\nbuilding of water/sewer infrastructure can be time consuming and may impact on other\nservices and building, driveway or landscape design.\nThe Notice of Requirements must be submitted to the Principal Certifying Authority prior to\nissue of the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"55","code":null,"number":"55","title":"Present Plans to Sydney Water","text":"Approved plans must be submitted online using Sydney Water Tap, available through\nwww.sydneywater.com.au to determine whether the development will affect Sydney Water's\nsewer and water mains, stormwater drains and/or easements, and if further requirements need to\nbe met.\nThe Certifying Authority must ensure that Sydney Water has issued an approval receipt prior to the\nissue of a Construction Certificate.\nVisit www.sydneywater.com.au or telephone 13 20 92 for further information.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"56","code":null,"number":"56","title":"Endeavour Energy Requirements","text":"The submission of documentary evidence from Endeavour Energy to the Principal Certifying\nAuthority is required confirming that satisfactory arrangements have been made with Endeavour\nEnergy for the provision of electricity supplies to the development, prior to the release of the\nConstruction Certificate.\nNote: Applications should be made to Customer Connections - South Coast, Endeavour Energy\nPO Box 811 Seven Hills NSW 1730.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"57","code":null,"number":"57","title":"Substation Design","text":"Prior to the release of a Construction Certificate, the developer shall obtain and provide evidence\nof Endeavour Energy’s approval of the substation design.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"58","code":null,"number":"58","title":"Telecommunications","text":"The submission of documentary evidence from an approved telecommunications carrier to the\nPrincipal Certifying Authority confirming that underground telecommunication services are\navailable for this development is required prior to the issue of the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"59","code":null,"number":"59","title":"Utility Services","text":"Should a proposed Vehicular Crossing be located where it is likely to disturb or impact upon a utility\ninstallation (ie power pole, Telstra pit etc) written confirmation from the affected supplier that they\nhave agreed to the proposed impacts shall be submitted to the Principal Certifying Authority prior\nto the issue of the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"60","code":null,"number":"60","title":"","text":"The arrangements and costs associated with any adjustment to a public utility service shall be\nborne by the applicant/developer. Any adjustment, deletion and/or creation of public utility\neasements associated with the approved works are the responsibility of the applicant/developer.\nThe submission of documentary evidence to the Principal Certifying Authority which confirms that\nsatisfactory arrangements have been put in place regarding any adjustment to such services is\nrequired prior to the release of the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"61","code":null,"number":"61","title":"","text":"The depth and location of all services (ie gas, water, sewer, electricity, telephone, traffic lights, etc)\nmust be ascertained and reflected on the Construction Certificate plans and supporting\ndocumentation.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"62","code":null,"number":"62","title":"Dilapidation Report Prior to Construction","text":"A Dilapidation Report detailing the current structural condition of the existing streetscape, street\ntrees and neighbouring buildings prior to work commencing and include a detailed description of\nelements and a photographic record. The report shall be prepared and endorsed by a qualified\nstructural engineer.\nThe report shall be submitted to the satisfaction of the Certifying Authority prior to issue of the\nConstruction Certificate. The report shall also identify the condition of all Council assets in the\nvicinity of the proposed works.\nA copy of the report is to be forwarded to Council and the owners of adjoining properties prior to\nthe issue of a Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"63","code":null,"number":"63","title":"Lighting of western façade, forecourt and Denison Street entry","text":"Provision should be made for lighting in and around the Denison Street primary entry and the west-\nfacing forecourt area. The lighting scheme shall provide for quality lighting to the forecourt area\nand entries to provide for safe access and a night-time presence. Details demonstrating compliance\nshall be provided to Council for approval prior to the release of the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"64","code":null,"number":"64","title":"Glass Reflectivity Index","text":"The reflectivity index of the glass and other finishing materials used in the external façade of the\nbuilding shall not exceed 20 per cent. The details and samples of the glass to be used are to be\nsubmitted with the Construction Certificate together with written evidence that the reflectivity of\nthe glass is 20 per cent or less.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"65","code":null,"number":"65","title":"External Finishes","text":"The building shall be constructed and finished in accordance with the approved schedule of\nfinishing materials and colours except where amended by conditions of this consent. This\nrequirement shall be reflected on the Construction Certificate plans and supporting\ndocumentation.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"66","code":null,"number":"66","title":"","text":"Pedestrian access ways, entry paths and lobbies must be constructed with durable materials\ncommensurate with the standard of the adjoining public domain with appropriate slip resistant\nmaterials, tactile surfaces and contrasting colours.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"67","code":null,"number":"67","title":"Finish of Vehicular Entries","text":"Vehicular entries are to have high quality finishes to walls and ceilings as well as high standard\ndetailing. No ducts or pipes are to be visible from the street.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"68","code":null,"number":"68","title":"Placement of Air Conditioning Units","text":"Air conditioning systems are to not to be located where they are visible from Denison or Hercules\nStreets. Plans submitted to the Principal Certifying Authority prior to issue of the Construction\nCertificate are to identify any external components of air conditioning systems to ensure they meet\nthe requirements of this condition.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"69","code":null,"number":"69","title":"Integration of Rooftop Structures in Approved Building Envelope","text":"All rooftop or exposed structures including lift rooms, plant rooms together with air conditioning\nunits, ventilation and exhaust systems are to be integrated within the approved rooftop envelope.\nThis requirement shall be reflected on the Construction Certificate plans.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"70","code":null,"number":"70","title":"Mechanical Ventilation of the Car park","text":"The car park shall be mechanically ventilated, to be ducted to the roof. Details demonstrating\ncompliance shall be provided with the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"71","code":null,"number":"71","title":"External Lighting","text":"Any lighting of external areas within the development shall be designed and located in a manner to\nprevent light spill and/ or glare impacts on neighbouring properties. Light placement and design\nshall be indicated on the construction certificate drawings.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"72","code":null,"number":"72","title":"Car Parking and Access","text":"The development shall make provision for the following:\n• 193 car parking spaces (including 5 disabled car parking spaces)\n• 8 motorcycle parking spaces\n• 58 secure (Class B) employee bicycle spaces\n16 visitor bicycle spaces (Class C)\nThis requirement shall be reflected on the Construction Certificate plans. Any change in the above\nparking numbers shown on the approved DA plans shall be dealt with via a section 96 modification\nto the development. The approved parking spaces shall be maintained to the satisfaction of\nCouncil, at all times.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"73","code":null,"number":"73","title":"","text":"The parking dimensions, internal circulation, aisle widths, kerb splay corners, head clearance\nheights, ramp widths and grades of the car parking areas are to be in conformity with the current\nrelevant Australian Standard AS2890.1, except where amended by other conditions of this consent.\nDetails of such compliance are to be reflected on the Construction Certificate plans.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"74","code":null,"number":"74","title":"","text":"Each disabled person’s parking space must comply with the current relevant Australian Standard\nAS2890.6 - Off-street parking for people with disabilities. This requirement shall be reflected on\nthe Construction Certificate plans.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"75","code":null,"number":"75","title":"","text":"The designated loading/unloading facility shall be kept clear for that purpose at all times. The\ndesignated loading/unloading facility shall be shown on the Construction Certificate plans.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"76","code":null,"number":"76","title":"","text":"The development shall make provision for suitable barriers, line-marking and painted signage\ndelineating vehicular flow movements within the car parking areas. These details shall be reflected\non the Construction Certificate plans.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"77","code":null,"number":"77","title":"","text":"A change in driveway paving is required at the entrance threshold within the property boundary to\nclearly show motorists they are crossing a pedestrian area. Between the property boundary and the\nkerb, the developer must construct the driveway pavement in accordance with the conditions,\ntechnical specifications and levels to be obtained from Council's Manager Works. This requirement\nshall be reflected on the Construction Certificate plans and any supporting documentation.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"78","code":null,"number":"78","title":"","text":"Any proposed structures adjacent to the driveway shall comply with the requirements of the\ncurrent relevant Australian Standard AS2890.1 to provide for adequate sight distance. This\nincludes, but is not limited to, structures such as signs, letterboxes, retaining walls, dense planting\netc. This requirement shall be reflected on the Construction Certificate plans.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"79","code":null,"number":"79","title":"","text":"Bicycle parking facilities must have adequate weather protection and provide the appropriate level\nof security as required by the current relevant Australian Standard AS2890.3 - Bicycle Parking\nFacilities and Austroads Guide to Traffic Management Part 11: Parking (Commentary 9: C9.2). This\nrequirement shall be reflected on the Construction Certificate plans.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"80","code":null,"number":"80","title":"","text":"Gradients of ramps and access driveways shall be provided in accordance with the current relevant\nAustralian Standard AS2890.1 - Off Street Car Parking. This requirement shall be reflected on the\nConstruction Certificate plans.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"81","code":null,"number":"81","title":"Detailed Drainage Design","text":"A detailed drainage design shall be submitted with the Construction Certificate documentation for\nthe proposed development. This detailed drainage design shall be prepared by a suitably qualified\ncivil engineer in accordance with Chapter E14 of Wollongong City Council’s Development Control\nPlan 2009, conditions listed under this consent, and generally in accordance with The Civil Design\nGround Level Stormwater Drainage Plan, Job no. 17020036, drawing no. C01, rev P3, by Jones\nNicholson, dated 08/05/2018.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"82","code":null,"number":"82","title":"On-Site Detention - Design Criteria","text":"The on-site stormwater detention facility shall incorporate a minimum 900mm x 900mm square\nlockable grate for access and maintenance purposes, provision for safety, debris control screen and\na suitably graded invert to the outlet to prevent ponding. Also, details of the orifice plate including\ndiameter of orifice and method of fixing shall be provided. These requirements shall be reflected on\nthe Construction Certificate plans.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"83","code":null,"number":"83","title":"On-Site Detention - Identification","text":"The construction certificate plans are to detail a corrosion resistant identification plaque for\nlocation on or close to the on-site stormwater detention (OSD) facility. The plaque shall include the\nfollowing information and shall be installed prior to the issue of the occupation certificate:\nThe structure is an OSD facility, being part of the stormwater drainage network, and is not to be\ntampered with.\nIdentification number - DA-2017/1729\nAny specialist maintenance requirements.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"84","code":null,"number":"84","title":"Orifice/Weir Calculations","text":"Orifice and weir calculations for the on-site detention facility shall be provided to the Principal\nCertifying Authority for approval prior to the issue of the Construction Certificate. The orifice shall\nbe of circular shape, designed to allow free discharge and have no influence from any tailwater\nlevels in the downstream drainage system.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"85","code":null,"number":"85","title":"Roofwater Drainage","text":"All roof gutters and downpipes designed to convey impervious area to the OSD system shall be\ndesigned to cater for a 1 in 100 year ARI storm event in accordance with the current version of AS\n3500.3 - Plumbing and Drainage (Stormwater Drainage). Details of gutter/downpipe sizes and\ndownpipe locations shall be reflected on the Construction Certificate plans.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"86","code":null,"number":"86","title":"Council Footpath Reserve Works","text":"All redundant vehicular crossings and laybacks rendered unnecessary by this development must be\nreconstructed to normal kerb and gutter to match the existing. The verge from the back of kerb to\nthe boundary must be removed and the area appropriately graded, topsoiled and turfed in a\nmanner that conforms with adjoining road reserve. The area forward of the front boundary must\nbe kept smooth, even and free from any trip hazards. All alterations of public infrastructure where\nnecessary are at the developer’s expense.\nAll new driveway laybacks and driveway crossings must be designed in accordance with\nWollongong City Council Standards. Details and locations are to be shown on the Construction\nCertificate Plans.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"87","code":null,"number":"87","title":"Retaining Wall on Common Boundary","text":"Retaining wall on common boundary must be located wholly within the property, including footings\nand agricultural drainage lines. Construction of retaining walls or associated drainage work along\ncommon boundaries must not compromise the structural integrity of any existing structures.\nThe maximum height of a retaining wall located within 900mm of the adjoining boundary shall be\n600mm unless approved within this Development Application.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"88","code":null,"number":"88","title":"Excavation and Retaining Structures adjacent to Public Road","text":"The design of all permanent and temporary retaining structures within the zone of influence of any\nCouncil assets including the road pavement, stormwater pipes and pits, must be provided to\nWollongong City Council and the Principal Certifying Authority prior to the issue of the Construction\nCertificate. The design must be prepared in accordance with the RMS Technical direction GTD\n2012/001, by a qualified Civil Engineer, NPER 3 accreditation with the Institute of Engineers\nAustralia and experienced in structural design. The plan must clearly show that all components of\nthe retaining structure and associated drainage is wholly located within the subject site. The design\nmust be supported by:\n• A geotechnical report prepared in accordance with the requirements of the RMS Technical\ndirection GTD 2012/001.\n• A dilapidation survey of the existing Council infrastructure\n• Details of the proposed monitoring program for the excavation and retaining structures,\nand relevant threshold actions prepared in accordance with RMS Technical direction GTD\n2012/001.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"89","code":null,"number":"89","title":"Ground Anchors","text":"Permanent ground anchors are not permitted within the road reserve. Temporary ground anchors\ncan only be used where the Road Authority has provided written confirmation to the applicant for\ntheir use. Temporary anchors must be designed in accordance with RMS Technical Direction GTD\n2012/001.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"90","code":null,"number":"90","title":"Hercules and Denison Streets- Detailed Civil Engineering Design - Council Land","text":"A detailed civil engineering design shall be provided for the proposed footpath, drainage and road\nworks within the road reserve and/or Council Land. The detailed civil engineering design shall be\nprepared by a suitably qualified practicing civil engineer in accordance with the relevant Council\nengineering standards. The design plans shall be generally in accordance with the The Landscape\nConcept Plan, drawing no. 1827-LD01A, dated 15/11/2017 and The Civil Design Hercules Street, Job\nno. 17020036, drawing no. C10 (Rev P3) & C11 (Rev P1), by Jones Nicholson, dated 08/05/2018.\nThe design shall include:\na) Levels and details of all existing and proposed infrastructure/services such as kerb and\ngutter, public utility, pits, poles, fencing, stormwater drainage, adjacent road carriageway\ncrown, street signs (clearly identifying the type of sign) and footpath levels, and shall\nextend a minimum of 5 metres beyond the limit of works.\nb) Footpath longitudinal sections, Road Longitudinal Sections, and cross-sections at 10 metre\nintervals as well as including building entrance points and transitions to existing at the\nproperty boundary demonstrating compliance with the latest versions of AS 1428.1,\nAS/NZS 2890.1, the Disability Discrimination Act and the AUSTROAD road design standards.\nc) Vehicular access must be provided for the adjoining lots on Hercules Street, details of the\nproposed vehicular crossings to access the lots must be provided.\nd) Engineering details of the proposed pit and pipe stormwater drainage system within\nCouncil’s road reserve, including a hydraulic grade line analysis and longitudinal section of\nthe proposed system showing calculated flows, velocity, pits, pipe size/class, grade, inverts\nand ground levels. Each proposed pit must be constructed generally in accordance with\nWollongong City Council’s Engineering Standard Drawings.\ne) Where any adjustments to public utilities are proposed the applicant shall submit\ndocumentary evidence that they have the consent of the owner of the public utility\nauthority.\nf) All construction must be in accordance with the requirements of Council’s Subdivision\nCode. Evidence that this requirement has been met must be detailed on the engineering\ndrawings.\ng) Details are to be provided regarding the type of materials used for construction. They\nshould conform to the adjacent road reserves.\nThe detailed civil engineering design and supporting documentation shall be submitted to and\napproved by Wollongong City Council’s Development Engineering Manager prior to the issue of a\nConstruction Certificate\n90A Hercules Street Construction\nAll road, civil engineering, drainage and associated public domain works associated with the construction\nof Hercules Street from its intersection with Denison Street to its eastern termination, shall be carried out\nby the developer. All works shall be completed prior to the release of the Occupation Certificate.\n90B Cost of Road Works - Hercules Street Construction\nThe cost of all road, civil engineering, drainage and associated public domain works associated with\nthe construction of Hercules Street, as required by Condition 90B, shall be borne by the developer\nand will be at no cost to Wollongong City Council or the NSW Roads & Maritime Services. All works\nshall be completed prior to the release of the Occupation Certificate.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"91","code":null,"number":"91","title":"Basement Waterproofing","text":"Full engineering details of the proposed wall around the basement car park shall be submitted to\nthe Principal Certifying Authority prior to the issue of the Construction Certificate. These shall\ninclude construction details indicating that no ingress of stormwater is possible into the basement\nlevels other than from sub-soil drainage, vehicle wash water and runoff from the driveway that\ndrains towards the basement. This applies to any proposed opening such as doors or ventilation\nlouvres. The problem of backwater from the stormwater pipeline entering the basement car park\nlevel shall be addressed by a method such as a flap gate or one-way valve system.","stage":"before_cc","stage_basis":"heading","page":17},{"label":"92","code":null,"number":"92","title":"Pump System","text":"A pump system shall be provided in association with the detailed drainage design for the site to\ncater for stormwater from a prolonged/extreme storm event entering the basement. The pump\nsystem shall be designed by a suitably qualified and experienced civil engineer and reflected on the\nConstruction Certificate plans and supporting documentation.","stage":"before_cc","stage_basis":"heading","page":17},{"label":"93","code":null,"number":"93","title":"Protection of Buildings from Ingress of Stormwater Runoff","text":"Detailed design of the development shall ensure that there will be no ingress of surface stormwater\nrunoff into the proposed buildings. All building entrances shall be provided with a suitable\nfreeboard above the adjacent local blocked pipe situation 100 year ARI water surface level. These\nrequirements shall be reflected on the Construction Certificate plans and supporting\ndocumentation prior to the release of the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":18},{"label":"94","code":null,"number":"94","title":"On Site Detention Structural Design","text":"The on-site detention facility located within the proposed driveway shall withstand the maximum\nloading and configuration imposed by the heaviest vehicle likely to use the accessway as specified\nin the RTA Heavy Vehicle Mass Loading and Access documentation, and applied in accordance with\nthe current code: AS/NZS 1170 - Structural Design Actions. The design loading adopted, and details\nof this detention facility shall be submitted prior to the release of the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":18},{"label":"95","code":null,"number":"95","title":"On-site Detention - Structural Design","text":"The on-site detention facility must be designed to withstand loadings occurring from any\ncombination of hydrostatic, earth, traffic and buoyancy forces. Details must be provided\ndemonstrating these requirements have been achieved prior to the issue of the Construction\nCertificate","stage":"before_cc","stage_basis":"heading","page":18},{"label":"96","code":null,"number":"96","title":"On-Site Detention - Maintenance Schedule","text":"A maintenance schedule for the on-site stormwater detention system must be submitted with the\nConstruction Certificate plans for the proposed development. The maintenance schedule must be\nin accordance with Chapter E14 of the Wollongong DCP2009.","stage":"before_cc","stage_basis":"heading","page":18},{"label":"97","code":null,"number":"97","title":"Overflow Paths","text":"Overflow paths must be provided to allow for flows of water in excess of the capacity of the\npipe/drainage system draining the land, as well as from any detention storage on the land. Blocked\npipe situations with 1 in 100 year ARI events must be incorporated in the design. Overflow paths\nmust also be provided in low points and depressions. This requirement shall be reflected on the\nConstruction Certificate plans prior to the release of the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":18},{"label":"98","code":null,"number":"98","title":"Details of Proposed Method of Connection of OSD","text":"Details of the proposed method of connection of the On-site Detention (OSD) facility to Council’s\ndrainage system must be provided with the detailed drainage design for the site. The details must\nbe submitted to the Principal Certifying Authority prior to the issue of the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":18},{"label":"99","code":null,"number":"99","title":"Provide OSD","text":"The developer must provide on-site detention storage for stormwater runoff from the\ndevelopment. The Site Storage Requirement (SSR) and Permissible Site Discharge (PSD) values for\nthe site must be designed in accordance with Chapter E14 of the Wollongong DCP2009. Details of\nthe detention facility and SSR/PSD values must be submitted with the Construction Certificate\napplication.","stage":"before_cc","stage_basis":"heading","page":18},{"label":"100","code":null,"number":"100","title":"Engineering Plans and Specifications - Retaining Wall Structures Greater than 1m","text":"The submission of engineering plans and supporting documentation of all proposed retaining walls\ngreater than 1m to the Principal Certifying Authority for approval prior to the issue of the\nConstruction Certificate. The retaining walls shall be designed by a suitably qualified and\nexperienced civil and/or structural engineer. The required engineering plans and supporting\ndocumentation shall include the following:","stage":"before_cc","stage_basis":"heading","page":18},{"label":"1","code":null,"number":"1","title":"","text":"A plan of the wall showing location and proximity to property boundaries;","stage":"before_cc","stage_basis":"heading","page":19},{"label":"2","code":null,"number":"2","title":"","text":"Sn elevation of the wall showing ground levels, maximum height of the wall, materials to be\nused and details of the footing design and longitudinal steps that may be required along the\nlength of the wall;","stage":"before_cc","stage_basis":"heading","page":19},{"label":"3","code":null,"number":"3","title":"","text":"Details of fencing or handrails to be erected on top of the wall;","stage":"before_cc","stage_basis":"heading","page":19},{"label":"4","code":null,"number":"4","title":"","text":"Sections of the wall showing wall and footing design, property boundaries and backfill\nmaterial. Sections shall be provided at sufficient intervals to determine the impact of the wall\non existing ground levels. The developer shall note that the retaining wall and footing\nstructure must be contained wholly within the subject property;","stage":"before_cc","stage_basis":"heading","page":19},{"label":"5","code":null,"number":"5","title":"","text":"The proposed method of subsurface and surface drainage, including water disposal;","stage":"before_cc","stage_basis":"heading","page":19},{"label":"6","code":null,"number":"6","title":"","text":"Reinforcing and joining details of any bend in the wall at the passing bay of the accessway;","stage":"before_cc","stage_basis":"heading","page":19},{"label":"7","code":null,"number":"7","title":"","text":"The assumed loading used by the engineer for the wall design.","stage":"before_cc","stage_basis":"heading","page":19},{"label":"8","code":null,"number":"8","title":"","text":"Flows from adjoining properties shall be accepted and catered for within the site. Finished\nground and top of retaining wall levels on the boundary shall be no higher than the existing\nupslope adjacent ground levels.\n101 Landscaping\nThe submission of a final Landscape Plan will be required in accordance with the requirements of\nChapter E6 of Wollongong Development Control Plan (DCP) 2009 and the submitted Landscape\nPlan for the approval by the Principal Certifying Authority, prior to the release of the Construction\nCertificate. The final landscape plan shall make provision for the required street tree planting and\nfootpath paving works as required by other conditions of this consent.\nThe completion of the landscaping works as per the final approved Landscape Plan is required,\nprior to the issue of Occupation Certificate.\n102 Landscape and Drainage Compatibility\nThe submission of certification from a suitably qualified and experienced landscape designer and\ndrainage consultant to the Principal Certifying Authority prior to the release of the Construction\nCertificate, confirming that the landscape plan and the drainage plan are compatible.\n103 Landscape Maintenance Program\nThe implementation of a landscape maintenance program in accordance with the approved\nLandscape Plan for a minimum period of 12 months to ensure that all landscape work becomes well\nestablished by regular maintenance. Details of the program must be submitted with the Landscape\nPlan to the Principal Certifying Authority prior to release of the Construction Certificate.\n104 Footpath Paving City Centre\nThe developer is responsible for the construction of footpath paving for the entire frontage of the\ndevelopment for the full width of the verge. The type of paving for this development shall be in\naccordance with the Wollongong City Council Public Domain Technical Manual.\nA nominal two percent (2%) minimum one percent (1%), maximum two and a half percent (2.5%)\ncross fall to be provided from property line to back of kerb. Any changes of level, ramps or stairs\nand associated tactile markers and handrails are to be contained with the property boundary.\nThe driveway entry threshold from the property boundary line to the face of kerb is to match the\nfootpath material and be designed to withstand predicted traffic loadings.\nThe driveway threshold finish within property boundary line is to contrast with driveway entry.\nThe footpath and driveway entry on the council property must be installed to the satisfaction of\nWCC Manager of Works.\nA Landscape Plan is to be submitted to Council for approval prior to the issue of the Construction\nCertificate showing proposed paving, footpath design levels, street tree details and location of all\nservices.\n105 Engineering Plans and Specifications - Retaining Wall Structures\nThe submission of engineering plans and supporting documentation of all proposed retaining walls\nto the Principal Certifying Authority for approval prior to the issue of the Construction Certificate.\nThe retaining walls shall be designed by a suitably qualified and experienced civil and/or structural\nengineer. The required engineering plans and supporting documentation shall include the\nfollowing, where applicable:\na A plan of the wall showing location and proximity to property boundaries;\nb an elevation of the wall showing ground levels, maximum height of the wall, materials to\nbe used and details of the footing design and longitudinal steps that may be required along\nthe length of the wall;\nc details of fencing or handrails to be erected on top of the wall;\nd sections of the wall showing wall and footing design, property boundaries and backfill\nmaterial. Sections shall be provided at sufficient intervals to determine the impact of the\nwall on existing ground levels. The developer shall note that the retaining wall and footing\nstructure must be contained wholly within the subject property;\ne the proposed method of subsurface and surface drainage, including water disposal;\nf reinforcing and joining details of the bends in the wall at the passing bay of the accessway;\ng the assumed traffic loading used by the engineer for the wall design.\n106 Property Addressing Policy Compliance\nPrior to the issue of any construction certificate, the developer must ensure that any site\naddressing complies with Council’s Property Addressing Policy (as amended). Where appropriate,\nthe developer must also lodge a written request to Council’s\nInfrastructure Systems & Support - Property Addressing\n(propertyaddressing@wollongong.nsw.gov.au), for the site addressing prior to the issue of the\nconstruction certificate. Enquiries regarding property addressing may be made by calling\n4227 8660.\n107 External Lighting\nAny lighting of external areas within the development such as driveways and car parking entry,\nshall be designed and located in a manner to prevent light spill and/ or glare impacts on\nneighbouring properties. Light placement and design shall be indicated on the Construction\nCertificate drawings.\n108 Crime Prevention\nCCTV shall be installed throughout the basement levels. Any CCTV installed at the site shall comply\nwith relevant legislation and guidelines regarding SOPs, image retention, access and placement.\n109 Lighting within the basement levels should meet Australian and New Zealand Lighting Standards, as\noutlined in AS 1158 for public streets, car parks and pedestrian areas. The generally accepted\nyardstick is lighting should be bright and even enough to permit an observer to see inside a parked\nvehicle.\n110 Site Management, Pedestrian and Traffic Management Plan (Where Works are Proposed in a\nPublic Road Reserve)\nThe submission of a Site Management, Pedestrian and Traffic Management Plan to the Principal\nCertifying Authority and Council (in the event that Council is not the Principal Certifying Authority)\nfor approval of both the Principal Certifying Authority and Council is required, prior to the issue of\nthe Construction Certificate. This plan shall address what measures will be implemented for the\nprotection of adjoining properties, pedestrian safety and traffic management and shall be in\ncompliance with the requirements of the latest versions of Australian Standard AS1742 - Traffic\nControl Devices for Works on Roads and the RMS Traffic Control at Worksites Manual.\nThis plan is required to maintain public safety, minimise disruption to pedestrian and vehicular\ntraffic within this locality and to protect services, during demolition, excavation and construction\nphases of the development. This plan shall include the following aspects:\na proposed ingress and egress points for vehicles to/from the construction site;\nb proposed protection of pedestrians, adjacent to the construction site;\nc proposed pedestrian management whilst vehicles are entering/exiting the construction\nsite;\nd proposed measures to be implemented for the protection of all roads and footpath areas\nsurrounding the construction site from building activities, crossings by heavy equipment,\nplant and materials delivery and static load from cranes, concrete pumps and the like;\ne proposed method of loading and unloading excavation machines, building materials\nformwork and the erection of any part of the structure within the site;\nf proposed areas within the site to be used for the storage of excavated material,\nconstruction materials and waste containers during the construction period;\ng proposed traffic control measures such as advanced warning signs, barricades, warning\nlights, after hours contact numbers etc are required to be displayed where works are in\nprogress in any road reserve and shall be in accordance the latest versions of the NSW\nRoads and Maritime Service’s Specification - “Traffic Control at Work Sites Manual” and the\nAustralian Standard AS1742. - “Manual of Uniform Traffic Control Devices” and\naccompanying field handbooks (SAA HB81);\nh proposed method of support of any excavation, adjacent to adjoining buildings or the road\nreserve. The proposed method of support is to be certified by an accredited certifier in Civil\nEngineering; and\ni proposed measures to be implemented, in order to ensure that no soil/excavated material\nis transported on wheels or tracks of vehicles or plant and deposited on the roadway.\nThe approved plan shall be implemented, prior to the commencement of any works upon the\nconstruction site.\nNote: Any proposed works or placement of plant and equipment and/or materials within any road\nreserve will require the separate approval of Council, prior to the commencement of such works,\npursuant to the provisions of the Roads Act 1993.\n111 Works in Road Reserve\nPrior to the issue of a Construction Certificate, the owner or contractor shall provide evidence to\nthe Council of a Public Risk Insurance Policy with a minimum cover of $10 million in relation to the\noccupation of and works within Council’s road reserve, for the full duration of the proposed works.\nThe policy is to note Council as an interested party.\n112 Supervision of Works within Road Reserve\nThe works within Council’s road reserve shall be supervised by a suitably qualified and experienced\nCivil Engineer or Civil Engineering Foreman. The supervisor’s name, address and contact details\n(including telephone number), together with a written construction program and anticipated\nduration of the construction works shall be submitted to Council’s Development Engineering\nManager prior to the commencement of works within the road reserve.\n113 Development Contributions - City Centre\nPursuant to Section 4.17 of the Environmental Planning and Assessment Act 1979 and the\nWollongong Section 94A Development Contributions Plan (2017), a monetary contribution of\n$410,000.00 (subject to indexation) must be paid to Council towards the provision of public\namenities and services, prior to the release of any associated Construction Certificate.\nThis amount has been calculated based on the estimated cost of development and the applicable\npercentage rate as outlined in Clause 25K of the Environmental Planning and Assessment\nRegulation 2000.\nThe contribution amount will be subject to indexation until the date of payment. The formula for\nindexing the contribution is:\nContribution at time of payment = $C x (CP2/CP1)\nWhere:\n$C is the original contribution as set out in the Consent\nCP1 is the Consumer Price Index; All Groups CPI; Sydney at the time the consent was issued\nCP2 is the Consumer Price Index; All Groups CPI; Sydney at the time of payment\nDetails of CP1 and CP2 can be found in the Australian Bureau of Statistics website - Catalogue No.\n6401.0 - Consumer Price Index, Australia.\nThe following payment methods are available:\nMETHOD HOW PAYMENT TYPE\nOnline http://www.wollongong.nsw.gov.au/applicationpay\nments\nYour Payment Reference: 920865\n• Credit Card\nIn Person Wollongong City Council\nAdministration Building - Customer Service Centre\nGround Floor 41 Burelli Street, WOLLONGONG\n• Cash\n• Credit Card\n• Bank Cheque\nPLEASE MAKE BANK CHEQUE PAYABLE TO: Wollongong City Council\n(Personal or company cheques are not accepted)\nA copy of the Wollongong Section 94A Development Contributions Plan (2017) and accompanying\nFact Sheet may be inspected or obtained from the Wollongong City Council Administration\nBuilding, 41 Burelli Street, Wollongong during business hours or on Council's web site at\nwww.wollongong.nsw.gov.au","stage":"before_cc","stage_basis":"heading","page":19},{"label":"1","code":null,"number":"1","title":"","text":"The concentration of suspended solids in the water to be discharged does not exceed 50 mg/L;\nand","stage":"before_work","stage_basis":"heading","page":29},{"label":"2","code":null,"number":"2","title":"","text":"The pH of the water to be discharged is between 6.5 and 8.5; and","stage":"before_work","stage_basis":"heading","page":29},{"label":"3","code":null,"number":"3","title":"The water to be discharged contains no visible oil or grease; and","text":"","stage":"before_work","stage_basis":"heading","page":29},{"label":"4","code":null,"number":"4","title":"","text":"If alum has been used to reduce suspended solids, the concentration of aluminium in the water\nto be discharged does not exceed 0.055 mg/L; and","stage":"before_work","stage_basis":"heading","page":29},{"label":"5","code":null,"number":"5","title":"","text":"The water to be discharged does not contain any substances known to be toxic to aquatic life;\nand","stage":"before_work","stage_basis":"heading","page":29},{"label":"6","code":null,"number":"6","title":"","text":"The flow rate of discharged water does not exceed 55 litres per second in dry weather conditions,\nor is less than the capacity of the receiving stormwater drain; and","stage":"before_work","stage_basis":"heading","page":29},{"label":"7","code":null,"number":"7","title":"","text":"A copy from a NATA accredited laboratory of sample test results for suspended solids and pH\n(and aluminium if applicable) confirming the water to be discharged meets criteria 1 and 2 (and\ncriteria 4 if applicable) as stated above is submitted to Council’s Environment Planning Team\n(phone 4227 7111; fax 4227 7277; email records@wollongong.nsw.gov.au, attention\nEnvironment Planning Team Manager); and","stage":"before_work","stage_basis":"heading","page":29},{"label":"8","code":null,"number":"8","title":"Written permission is obtained from Council’s Environment Planning Team prior to any","text":"discharge.\nAlternatively, such waters are to be removed by tanker for disposal at a NSW Environment\nProtection Authority licensed waste facility.\n156 Provision of Taps/Irrigation System\nThe provision of common taps and/or an irrigation system is required to guarantee that all\nlandscape works are adequately watered. The location of common taps and/or irrigation system\nmust be implemented in accordance with the approved Landscape Plan.\n157 Podium Planting\nAll podium planting areas are to have a waterproofing membrane that can provide a minimum 10\nyear warranty on product. Protective boarding is to be installed to protect membrane from\ndamage.\nAll podium planting areas to be provided with an adequate drainage system connected to the\nstormwater drainage system. The planter box is to be backfilled with free draining planter box soil\nmix.\nIf selected mulch is decorative pebbles/gravel, the maximum gravel pebble size is 10mm diameter\n158 Water Sensitive Urban Design\nWater sensitive urban design concept stated in WSUD Jones Nicholson Consulting Engineering\ndated December 2017 must be implemented.\n159 Site remediation and validation\nThe recommendations of the site assessment report must be implemented for remediation of the\nsite of the proposed development. The Contaminated Land Management Act 1997 and Chapter E20\nof Wollongong DCP 2009 must be considered for the proposed remediation works.\n160 Site Validation Report\nThe submission of a site validation report to Council is required, prior to the commencement of\nconstruction of the building. This validation report shall verify that:\n• all required site contamination remediation works have been satisfactorily completed;\n• the site is not affected by any soil strata and/or groundwater table contamination, above\nNSW EPA threshold limit criteria; and\n• the site is rendered suitable for the proposed development.\nThe report shall be prepared by qualified and experienced consultant who has one of the following\ncertification schemes: (a) the Site Contamination Practitioners Australia (SCPA) scheme; (b) the\nEnvironment Institute of Australia and New Zealand’s (EIANZ) Contaminated Land Assessment\nSpecialist Certified Environmental Practitioner (CLA Specialist CEnvP) scheme or (c) the Soil Science\nAustralia (SSA) Certified Professional Soil Scientist Contaminated Site Assessment and Management\n(CPSS CSAM) certification.","stage":"before_work","stage_basis":"heading","page":29}]});
